// Returns the first time t ∈ [0,1] at which the ball's path (prev → current)
// enters the brick's expanded box (brick inflated by the ball radius), plus
// the face(s) crossed at that entry: 'top' | 'bottom' | 'left' | 'right'.
// null when the path never enters the box.
// Reference: swept AABB slab method (see .scratch/to_fix.md D5).
function sweepEntry(ball, brick) {
  const x0 = ball.prevX ?? ball.x;
  const y0 = ball.prevY ?? ball.y;
  const dx = ball.x - x0;
  const dy = ball.y - y0;
  const minX = brick.x - ball.r;
  const maxX = brick.x + brick.w + ball.r;
  const minY = brick.y - ball.r;
  const maxY = brick.y + brick.h + ball.r;

  let tEnter = 0;
  let tExit = 1;
  const faces = [];

  const slab = (p0, d, lo, hi, inFace, outFace) => {
    if (d === 0) {
      return p0 >= lo && p0 <= hi;
    }
    const t1 = (lo - p0) / d;
    const t2 = (hi - p0) / d;
    const enter = Math.min(t1, t2);
    const leave = Math.max(t1, t2);
    if (enter > tEnter + EPS) {
