// --- Brick collision resolution (tested primitive) ------------------------

// Faces of the brick overlapped by the ball, ordered by least penetration
// (the face the ball entered most recently). A tie on the smallest value is
// a corner hit: both faces are reported so both axes can be flipped.
const EPS = 1e-9;

function overlapFaces(ball, brick) {
  const left = ball.x + ball.r - brick.x;
  const right = brick.x + brick.w - (ball.x - ball.r);
  const top = ball.y + ball.r - brick.y;
  const bottom = brick.y + brick.h - (ball.y - ball.r);
  const min = Math.min(left, right, top, bottom);
  const faces = [];
  if (Math.abs(left - min) <= EPS) faces.push('left');
  if (Math.abs(right - min) <= EPS) faces.push('right');
  if (Math.abs(top - min) <= EPS) faces.push('top');
  if (Math.abs(bottom - min) <= EPS) faces.push('bottom');
  return { faces };
}

// Resolves ball/brick contacts: destroys and scores every brick the ball
// overlaps, flips the ball's vertical velocity and pushes the ball out of
// each brick along the least-penetration axis (D1).
export function resolveBrickCollisions(state) {
  const { ball, bricks } = state;
  const hits = bricks.filter((b) => b.alive && collides(ball, b));
  for (const brick of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    ball.vy = -ball.vy;
  }
  for (const brick of hits) {
    for (const face of overlapFaces(ball, brick).faces) {
      if (face === 'top') ball.y = Math.min(ball.y, brick.y - ball.r);
      else if (face === 'bottom') ball.y = Math.max(ball.y, brick.y + brick.h + ball.r);
      else if (face === 'left') ball.x = Math.min(ball.x, brick.x - ball.r);
      else if (face === 'right') ball.x = Math.max(ball.x, brick.x + brick.w + ball.r);
    }
  }
}

