edits.newText:
// Resolves ball/brick contacts. Each pass handles the whole group of bricks
// the ball currently overlaps: every member is destroyed and scored once, the
// ball's velocity is flipped at most once per axis per call (D2: a seam hit
// must not cancel itself with two vy flips), and the ball is pushed out of
// each brick along its least-penetration face.
export function resolveBrickCollisions(state) {
  const { ball, bricks } = state;
  let flippedX = false;
  let flippedY = false;

  for (let pass = 0; pass <= bricks.length; pass++) {
    const group = bricks.filter((b) => b.alive && collides(ball, b));
    if (group.length === 0) break;

    for (const brick of group) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }

    if (!flippedY) {
      ball.vy = -ball.vy;
      flippedY = true;
    }

    for (const brick of group) {
      for (const face of overlapFaces(ball, brick).faces) {
        if (face === 'top') ball.y = Math.min(ball.y, brick.y - ball.r);
        else if (face === 'bottom') ball.y = Math.max(ball.y, brick.y + brick.h + ball.r);
        else if (face === 'left') ball.x = Math.min(ball.x, brick.x - ball.r);
        else if (face === 'right') ball.x = Math.max(ball.x, brick.x + brick.w + ball.r);
      }
    }
  }
}

