// Faces of the brick overlapped by the ball, ordered by least penetration
// (the face the ball entered most recently). A tie on the smallest value is
// a corner hit: both faces are reported so both axes can be flipped.
const EPS = 1e-9;

function overlapFaces(ball, brick) {
  const left = ball.x + ball.r - brick.x;
  const right = brick.x + brick.w - (ball.x - ball.r);
  const top = ball.y + ball.r - brick.y;
  const bottom = brick.y + brick.h - (ball.y - ball.r);
  const min = Math.min(left, right, top, bottom);
  const faces = [];
  if (Math.abs(left - min) <= EPS) faces.push('left');
  if (Math.abs(right - min) <= EPS) faces.push('right');
  if (Math.abs(top - min) <= EPS) faces.push('top');
  if (Math.abs(bottom - min) <= EPS) faces.push('bottom');
  return { faces };
}

// First entry of the ball's path (prev -> current) into the brick's expanded
// box (the brick inflated by the ball radius): swept AABB, slab method.
// Returns { t, faces } with t the entry time in [0,1] and faces the face(s)
// crossed at that instant, or null when the path never enters the box.
// A path that only touches the box boundary (tEnter == tExit, a graze) is
// not an entry: return null.
function sweepEntry(ball, brick) {
  const x0 = ball.prevX ?? ball.x;
  const y0 = ball.prevY ?? ball.y;
  const dx = ball.x - x0;
  const dy = ball.y - y0;
  const minX = brick.x - ball.r;
  const maxX = brick.x + brick.w + ball.r;
  const minY = brick.y - ball.r;
  const maxY = brick.y + brick.h + ball.r;

  let tEnter = 0;
  let tExit = 1;
  const faces = [];

  const slab = (p0, d, lo, hi, inFace, outFace) => {
    if (d === 0) return p0 >= lo && p0 <= hi;
    const t1 = (lo - p0) / d;
    const t2 = (hi - p0) / d;
    const enter = Math.min(t1, t2);
    const leave = Math.max(t1, t2);
    if (enter > tEnter + EPS) {
      tEnter = enter;
      faces.length = 0;
      faces.push(d > 0 ? inFace : outFace);
    } else if (Math.abs(enter - tEnter) <= EPS) {
      faces.push(d > 0 ? inFace : outFace);
    }
    if (leave < tExit) tExit = leave;
    return true;
  };

  if (!slab(x0, dx, minX, maxX, 'left', 'right')) return null;
  if (!slab(y0, dy, minY, maxY, 'top', 'bottom')) return null;
  if (tEnter > tExit || tEnter === tExit) return null; // no crossing, or a graze
  return { t: tEnter, faces };
}

// Resolves ball/brick contacts. Each pass handles the group of bricks whose
// expanded box the ball's path enters at (almost) the same instant — the
// earliest entry wins, so a brick crossed at full speed (D5) is still hit and
// a brick that only appears later in the path is left untouched. Every member
// of the group is destroyed and scored once, the ball's velocity is flipped
// at most once per axis per call (D2: a seam hit must not cancel itself with
// two vy flips), and the ball is pushed out along the entry faces (or the
// least-penetration faces when it was already inside at the start of the
// step).
export function resolveBrickCollisions(state) {
  const { ball, bricks } = state;
  let flippedX = false;
  let flippedY = false;

  for (let pass = 0; pass <= bricks.length; pass++) {
    let best = null;
    for (const brick of bricks) {
      if (!brick.alive) continue;
      const entry = sweepEntry(ball, brick);
      if (!entry) continue;
      if (!best || entry.t < best.entry.t - EPS) best = { brick, entry };
    }
    if (!best) break;

    const group = [];
    for (const brick of bricks) {
      if (!brick.alive) continue;
      const entry = sweepEntry(ball, brick);
      if (entry && Math.abs(entry.t - best.entry.t) <= EPS) group.push({ brick, entry });
    }

    for (const g of group) {
      g.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(g.brick, state.combo);
    }

    // Flip each axis at most once per call, on the entry face of the hit
    // (or the least-penetration face when already overlapping at start).
    for (const g of group) {
      const faces =
        g.entry.t > 0 ? g.entry.faces : overlapFaces(ball, g.brick).faces;
      for (const face of faces) {
        if (face === 'left' && !flippedX) {
          ball.vx = -Math.abs(ball.vx);
          flippedX = true;
        } else if (face === 'right' && !flippedX) {
          ball.vx = Math.abs(ball.vx);
          flippedX = true;
        } else if (face === 'top' && !flippedY) {
          ball.vy = -Math.abs(ball.vy);
          flippedY = true;
        } else if (face === 'bottom' && !flippedY) {
          ball.vy = Math.abs(ball.vy);
          flippedY = true;
        }
      }
    }

    // Push the ball out of the group along the hit faces.
    for (const g of group) {
      const faces =
        g.entry.t > 0 ? g.entry.faces : overlapFaces(ball, g.brick).faces;
      for (const face of faces) {
        if (face === 'top') ball.y = Math.min(ball.y, g.brick.y - ball.r);
        else if (face === 'bottom') ball.y = Math.max(ball.y, g.brick.y + g.brick.h + ball.r);
        else if (face === 'left') ball.x = Math.min(ball.x, g.brick.x - ball.r);
        else if (face === 'right') ball.x = Math.max(ball.x, g.brick.x + g.brick.w + ball.r);
      }
    }
  }
}

